        ///Interrupt before timeout. 1 = generate interrupt when counter reaches pre-timeout value (set in CTRL bits \[31:10\]).
        #[inline(always)]
        pub const fn set_WDT_INTR(&mut self, val: bool) {
            self.0 = (self.0 & !(0x01 << 2usize)) | (((val as u32) & 0x01) << 2usize);
        }
