        #[must_use]
        #[inline(always)]
        pub const fn WDT_EXT(&self) -> bool {
            let val = (self.0 >> 3usize) & 0x01;
            val != 0
        }
        ///External signal enable after timeout. 1 = pulse generated on an external output pin.
        #[inline(always)]
